import{_ as l,W as o,s as p,u as d,I as i,ah as r,w as e,Z as n,A as a}from"./chunks/framework.CW1q-D1p.js";import"./chunks/theme.DKZ8RGYq.js";const D=JSON.parse('{"title":"MidnightBSD：或许是你通往 FreeBSD 的大门 | LCTT x X-CMD","titleTemplate":false,"description":"MidnightBSD：或许是你通往 FreeBSD 的大门 | LCTT (202002) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"MidnightBSD：或许是你通往 FreeBSD 的大门 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"MidnightBSD：或许是你通往 FreeBSD 的大门 | LCTT (202002) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202002/20180511 MidnightBSD Could Be Your Gateway to FreeBSD","title":"MidnightBSD：或许是你通往 FreeBSD 的大门","tag":"202002"},"relativePath":"202002/20180511 MidnightBSD Could Be Your Gateway to FreeBSD.md","filePath":"[post].md"}'),u={name:"202002/20180511 MidnightBSD Could Be Your Gateway to FreeBSD.md"};function g(m,t,h,c,b,f){const s=o("Link");return d(),p("div",null,[t[29]||(t[29]=i("h1",{id:"midnightbsd-或许是你通往-freebsd-的大门",tabindex:"-1"},[e("MidnightBSD：或许是你通往 FreeBSD 的大门 "),i("a",{class:"header-anchor",href:"#midnightbsd-或许是你通往-freebsd-的大门","aria-label":"Permalink to MidnightBSD：或许是你通往 FreeBSD 的大门"},"​")],-1)),t[30]||(t[30]=i("p",null,[i("img",{src:"https://www.linux.com/wp-content/uploads/2019/08/midnight_4_0.jpg",alt:""})],-1)),i("p",null,[n(s,{href:"https://www.freebsd.org/"},{default:a(()=>t[0]||(t[0]=[e("FreeBSD")])),_:1}),t[4]||(t[4]=e(" 是一个开源操作系统，衍生自著名的 ")),i("ruby",null,[n(s,{href:"https://en.wikipedia.org/wiki/Berkeley_Software_Distribution"},{default:a(()=>t[1]||(t[1]=[e("伯克利软件套件")])),_:1}),t[2]||(t[2]=i("rt",null,"Berkeley Software Distribution",-1))]),t[5]||(t[5]=e("（BSD）。FreeBSD 的第一个版本发布于 1993 年，并且仍然在继续发展。2007 年左右，Lucas Holt 想要利用 OpenStep（现在是 Cocoa）的 Objective-C 框架、widget 工具包和应用程序开发工具的 ")),n(s,{href:"https://en.wikipedia.org/wiki/GNUstep"},{default:a(()=>t[3]||(t[3]=[e("GnuStep")])),_:1}),t[6]||(t[6]=e(" 实现，来创建一个 FreeBSD 的分支。为此，他开始开发 MidnightBSD 桌面发行版。"))]),t[31]||(t[31]=i("p",null,"MidnightBSD（以 Lucas 的猫 Midnight 命名）仍然在积极地（尽管缓慢）开发。从 2017 年 8 月开始，可以获得最新的稳定发布版本（0.8.6）（LCTT 译注：截止至本译文发布时，当前是 2019/10/31 发布的 1.2 版）。尽管 BSD 发行版不是你所说的用户友好型发行版，但上手安装是熟悉如何处理 文本（ncurses）安装过程以及通过命令行完成安装的好方法。",-1)),t[32]||(t[32]=i("p",null,"这样，你最终会得到一个非常可靠的 FreeBSD 分支的桌面发行版。这需要花费一点精力，但是如果你是一名正在寻找扩展你的技能的 Linux 用户……这是一个很好的起点。",-1)),t[33]||(t[33]=i("p",null,"我将带你走过安装 MidnightBSD 的流程，如何添加一个图形桌面环境，然后如何安装应用程序。",-1)),t[34]||(t[34]=i("h3",{id:"安装",tabindex:"-1"},[e("安装 "),i("a",{class:"header-anchor",href:"#安装","aria-label":"Permalink to 安装"},"​")],-1)),i("p",null,[t[9]||(t[9]=e("正如我所提到的，这是一个文本（ncurses）安装过程，因此在这里找不到可以用鼠标点击的地方。相反，你将使用你键盘的 ")),t[10]||(t[10]=i("code",null,"Tab",-1)),t[11]||(t[11]=e(" 键和箭头键。在你下载")),n(s,{href:"http://www.midnightbsd.org/download/"},{default:a(()=>t[7]||(t[7]=[e("最新的发布版本")])),_:1}),t[12]||(t[12]=e("后，将它刻录到一个 CD/DVD 或 USB 驱动器，并启动你的机器（或者在 ")),n(s,{href:"https://www.virtualbox.org/"},{default:a(()=>t[8]||(t[8]=[e("VirtualBox")])),_:1}),t[13]||(t[13]=e(" 中创建一个虚拟机）。安装程序将打开并给你三个选项（图 1）。使用你的键盘的箭头键选择 “Install”，并敲击回车键。"))]),t[35]||(t[35]=r(`<p><img src="https://lcom.static.linuxfound.org/sites/lcom/files/midnight_1.jpg" alt="MidnightBSD installer" title="MidnightBSD installer"></p><p><em>图 1: 启动 MidnightBSD 安装程序。</em></p><p>在这里要经历相当多的屏幕。其中很多屏幕是一目了然的：</p><ol><li>设置非默认键盘映射（是/否）</li><li>设置主机名称</li><li>添加可选系统组件（文档、游戏、32 位兼容性、系统源码代码）</li><li>对硬盘分区</li><li>管理员密码</li><li>配置网络接口</li><li>选择地区（时区）</li><li>启用服务（例如 ssh）</li><li>添加用户（图 2）</li></ol><p><img src="https://lcom.static.linuxfound.org/sites/lcom/files/midnight_2.jpg" alt="Adding a user" title="Adding a user"></p><p><em>图 2: 向系统添加一个用户。</em></p><p>在你向系统添加用户后，你将被进入到一个窗口中（图 3），在这里，你可以处理任何你可能忘记配置或你想重新配置的东西。如果你不需要作出任何更改，选择 “Exit”，然后你的配置就会被应用。</p><p><img src="https://lcom.static.linuxfound.org/sites/lcom/files/mightnight_3.jpg" alt="Applying your configurations" title="Applying your configurations"></p><p><em>图 3: 应用你的配置。</em></p><p>在接下来的窗口中，当出现提示时，选择 “No”，接下来系统将重启。在 MidnightBSD 重启后，你已经为下一阶段的安装做好了准备。</p><h3 id="后安装阶段" tabindex="-1">后安装阶段 <a class="header-anchor" href="#后安装阶段" aria-label="Permalink to 后安装阶段">​</a></h3><p>当你最新安装的 MidnightBSD 启动时，你将发现你自己处于命令提示符当中。此刻，还没有图形界面。要安装应用程序，MidnightBSD 依赖于 <code>mport</code> 工具。比如说你想安装 Xfce 桌面环境。为此，登录到 MidnightBSD 中，并发出下面的命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo mport index</span></span>
<span class="line"><span>sudo mport install xorg</span></span></code></pre></div><p>你现在已经安装好 Xorg 窗口服务器了，它允许你安装桌面环境。使用命令来安装 Xfce ：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo mport install xfce</span></span></code></pre></div><p>现在 Xfce 已经安装好。不过，我们必须让它同命令 <code>startx</code> 一起启用。为此，让我们先安装 nano 编辑器。发出命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo mport install nano</span></span></code></pre></div><p>随着 nano 安装好，发出命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nano ~/.xinitrc</span></span></code></pre></div><p>这个文件仅包含一行内容：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>exec startxfce4</span></span></code></pre></div><p>保存并关闭这个文件。如果你现在发出命令 <code>startx</code>, Xfce 桌面环境将会启动。你应该会感到有点熟悉了吧（图 4）。</p><p><img src="https://lcom.static.linuxfound.org/sites/lcom/files/midnight_4.jpg" alt=" Xfce" title="Xfce"></p><p><em>图 4: Xfce 桌面界面已准备好服务。</em></p><p>因为你不会总是想必须发出命令 <code>startx</code>，你希望启用登录守护进程。然而，它却没有安装。要安装这个子系统，发出命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo mport install mlogind</span></span></code></pre></div><p>当完成安装后，通过在 <code>/etc/rc.conf</code> 文件中添加一个项目来在启动时启用 mlogind。在 <code>rc.conf</code> 文件的底部，添加以下内容：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mlogind_enable=”YES”</span></span></code></pre></div><p>保存并关闭该文件。现在，当你启动（或重启）机器时，你应该会看到图形登录屏幕。在写这篇文章的时候，在登录后我最后得到一个空白屏幕和讨厌的 X 光标。不幸的是，目前似乎并没有这个问题的解决方法。所以，要访问你的桌面环境，你必须使用 <code>startx</code> 命令。</p><h3 id="安装应用" tabindex="-1">安装应用 <a class="header-anchor" href="#安装应用" aria-label="Permalink to 安装应用">​</a></h3><p>默认情况下，你找不到很多能可用的应用程序。如果你尝试使用 <code>mport</code> 安装应用程序，你很快就会感到沮丧，因为只能找到很少的应用程序。为解决这个问题，我们需要使用 <code>svnlite</code> 命令来查看检出的可用 mport 软件列表。回到终端窗口，并发出命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>svnlite co http://svn.midnightbsd.org/svn/mports/trunk mports</span></span></code></pre></div><p>在你完成这些后，你应该看到一个命名为 <code>~/mports</code> 的新目录。使用命令 <code>cd ~/.mports</code> 更改到这个目录。发出 <code>ls</code> 命令，然后你应该看到许多的类别（图 5）。</p><p><img src="https://lcom.static.linuxfound.org/sites/lcom/files/midnight_5.jpg" alt="applications" title="applications"></p><p><em>图 5: mport 现在可用的应用程序类别。</em></p><p>你想安装 Firefox 吗？如果你查看 <code>www</code> 目录，你将看到一个 <code>linux-firefox</code> 列表。发出命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo mport install linux-firefox</span></span></code></pre></div><p>现在你应该会在 Xfce 桌面菜单中看到一个 Firefox 项。翻找所有的类别，并使用 <code>mport</code> 命令来安装你需要的所有软件。</p><h3 id="一个悲哀的警告" tabindex="-1">一个悲哀的警告 <a class="header-anchor" href="#一个悲哀的警告" aria-label="Permalink to 一个悲哀的警告">​</a></h3><p>一个悲哀的小警告是，<code>mport</code> （通过 <code>svnlite</code>）仅能找到的一个办公套件的版本是 OpenOffice 3 。那是非常过时的。尽管在 <code>~/mports/editors</code> 目录中能找到 Abiword ，但是它看起来不能安装。甚至在安装 OpenOffice 3 后，它会输出一个执行格式错误。换句话说，你不能使用 MidnightBSD 在办公生产效率方面做很多的事情。但是，嘿嘿，如果你周围正好有一个旧的 Palm Pilot，你可以安装 pilot-link。换句话说，可用的软件不足以构成一个极其有用的桌面发行版……至少对普通用户不是。但是，如果你想在 MidnightBSD 上开发，你将找到很多可用的工具可以安装（查看 <code>~/mports/devel</code> 目录）。你甚至可以使用命令安装 Drupal ：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo mport install drupal7</span></span></code></pre></div><p>当然，在此之后，你将需要创建一个数据库（MySQL 已经安装）、安装 Apache（<code>sudo mport install apache24</code>），并配置必要的 Apache 配置。</p><p>显然地，已安装的和可以安装的是一个应用程序、系统和服务的大杂烩。但是随着足够多的工作，你最终可以得到一个能够服务于特殊目的的发行版。</p><h3 id="享受-bsd-优良" tabindex="-1">享受 *BSD 优良 <a class="header-anchor" href="#享受-bsd-优良" aria-label="Permalink to 享受 \\*BSD 优良">​</a></h3><p>这就是如何使 MidnightBSD 启动，并使其运行某种有用的桌面发行版的方法。它不像很多其它的 Linux 发行版一样快速简便，但是如果你想要一个促使你思考的发行版，这可能正是你正在寻找的。尽管大多数竞争对手都准备了很多可以安装的应用软件，但 MidnightBSD 无疑是一个 Linux 爱好者或管理员应该尝试的有趣挑战。</p><hr>`,46)),i("p",null,[t[15]||(t[15]=e("via: ")),n(s,{href:"https://www.linux.com/learn/intro-to-linux/2018/5/midnightbsd-could-be-your-gateway-freebsd"},{default:a(()=>t[14]||(t[14]=[e("https://www.linux.com/learn/intro-to-linux/2018/5/midnightbsd-could-be-your-gateway-freebsd")])),_:1})]),i("p",null,[t[20]||(t[20]=e("作者：")),n(s,{href:"https://www.linux.com/users/jlwallen"},{default:a(()=>t[16]||(t[16]=[e("Jack Wallen")])),_:1}),t[21]||(t[21]=e(" 选题：")),n(s,{href:"https://github.com/lujun9972"},{default:a(()=>t[17]||(t[17]=[e("lujun9972")])),_:1}),t[22]||(t[22]=e(" 译者：")),n(s,{href:"https://github.com/robsean"},{default:a(()=>t[18]||(t[18]=[e("robsean")])),_:1}),t[23]||(t[23]=e(" 校对：")),n(s,{href:"https://github.com/wxy"},{default:a(()=>t[19]||(t[19]=[e("wxy")])),_:1})]),i("p",null,[t[26]||(t[26]=e("本文由 ")),n(s,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>t[24]||(t[24]=[e("LCTT")])),_:1}),t[27]||(t[27]=e(" 原创编译，")),n(s,{href:"https://linux.cn/"},{default:a(()=>t[25]||(t[25]=[e("Linux中国")])),_:1}),t[28]||(t[28]=e(" 荣誉推出"))])])}const S=l(u,[["render",g]]);export{D as __pageData,S as default};
